(* [comment removed for export] *)
Lemma fpv_step_fsqrt : forall (fx : FPState) segs regs pc mem rom w fmt rd rs1 (rm : bv 3) md,
  fetch_word segs pc = Some w -> is_ecall w = false ->
  decode_any w = Some (Fsqrt fmt rd rs1 rm, 4%Z) ->
  frm_zero (@fp_csr fx) -> rmode_of_field (bv_unsigned rm) 0 = Some md ->
  RiscvSemantics.step segs (@mkst fx regs pc mem rom) =
  MachineOk (@mkst (mkFP (bvmap_set rd (fpv_box fmt (fst (fp_sqrt (fp_format fmt) md (fpv_read (@fp_regs fx) fmt rs1)))) (@fp_regs fx))
                         (fpv_acc (@fp_csr fx) (snd (fp_sqrt (fp_format fmt) md (fpv_read (@fp_regs fx) fmt rs1)))))
                   regs (v_addi pc 4) mem rom).
Proof.
