Section BridgesSq.
Variable segs : list Segment.

Lemma exf_fsqrt : forall E L fr cs rom R pc (M : word -> option byte) ms0 w fmt rd rs1 (rm : bv 3) md (w1 : word) (res zr : Z) (fl : fflags),
  msteps segs ms0 (@mkst (mkFP (fr_denot E L fr) cs) R (Z_to_bv 64 pc) M rom) ->
  fetch_word segs (Z_to_bv 64 pc) = Some w -> is_ecall w = false -> decode_any w = Some (Fsqrt fmt rd rs1 rm, 4%Z) ->
  frm_zero cs -> rmode_of_field (bv_unsigned rm) 0 = Some md ->
  reg_get (fr_denot E L fr) rs1 = w1 ->
  fp_sqrt (fp_format fmt) md (fpv_rdw fmt w1) = (res, fl) -> fpv_box fmt res = Z_to_bv 64 zr ->
  msteps segs ms0 (@mkst (mkFP (fr_denot E ((rd, ELit zr) :: L) fr) (fpv_acc cs fl)) R (Z_to_bv 64 (pc + 4)) M rom).
Proof.
