Lemma exf_fcvt_fx : forall E L fr cs rom R pc sr (M : word -> option byte) ms0 w dst src rd rs1 (rm : bv 3) md df sgn bits (z1 res zr : Z) (fl : fflags),
  msteps segs ms0 (@mkst (mkFP (fr_denot E L fr) cs) R (Z_to_bv 64 pc) M rom) -> regs_ok E sr R ->
  fetch_word segs (Z_to_bv 64 pc) = Some w -> is_ecall w = false -> decode_any w = Some (Fcvt dst src rd rs1 rm, 4%Z) ->
  (dst = FC_S /\ df = FMT_S \/ dst = FC_D /\ df = FMT_D) ->
  (src = FC_W /\ sgn = true /\ bits = 32%Z \/ src = FC_WU /\ sgn = false /\ bits = 32%Z \/
   src = FC_L /\ sgn = true /\ bits = 64%Z \/ src = FC_LU /\ sgn = false /\ bits = 64%Z) ->
  frm_zero cs -> rmode_of_field (bv_unsigned rm) 0 = Some md ->
  edenot E (sr_get sr rs1) = Z_to_bv 64 z1 ->
  fp_of_int (fp_format df) md sgn bits (bv_unsigned (Z_to_bv 64 z1)) = (res, fl) -> fpv_box df res = Z_to_bv 64 zr ->
  msteps segs ms0 (@mkst (mkFP (fr_denot E ((rd, ELit zr) :: L) fr) (fpv_acc cs fl)) R (Z_to_bv 64 (pc + 4)) M rom).
Proof.
