(* [comment removed for export] *)
Ltac exq_fstep fdef HK ST FZ :=
  lazymatch type of ST with
  | ex_st ?segs ?E ?m ?rom ?ms0 (mkFP (fr_denot _ ?L ?fr) ?cs) ?pc ?sr ?log =>
      let d := eval vm_compute in (match fetch_word segs (Z_to_bv 64 pc) with Some w => decode_any w | None => None end) in
      lazymatch d with
      | Some (Fsqrt ?fmt ?rd ?rs1 ?rm, _) =>
          let F := fresh "F" in let D := fresh "D" in let ST' := fresh "ST" in let G1 := fresh "G" in
          ex_fetch segs pc F D;
          lazymatch type of D with
          | decode_any ?w = _ =>
            let mdo := eval vm_compute in (rmode_of_field (bv_unsigned rm) 0) in
            let md := lazymatch mdo with Some ?md => md end in
            exf_closed E L fr rs1 G1 ltac:(fun z1 =>
              let r := eval vm_compute in (fp_sqrt (fp_format fmt) md (fpv_rdw fmt (Z_to_bv 64 z1))) in
              lazymatch r with (?res, ?fl) =>
                let zr := eval vm_compute in (bv_unsigned (fpv_box fmt res)) in
                pose proof (exb_fsqrt segs E L fr cs m rom pc sr log ms0 w fmt rd rs1 rm md (Z_to_bv 64 z1) res zr fl
                              ST F (eq_refl _) D FZ ltac:(vm_cast_no_check (eq_refl (Some md))) G1
                              ltac:(vm_cast_no_check (eq_refl (res, fl))) ltac:(apply bv_eq; vm_cast_no_check (eq_refl zr))) as ST';
                clear F D G1 ST; rename ST' into ST; exb_reabs ST FZ end)
          end
      | Some (Fcvt FC_D ?src ?rd ?rs1 ?rm, _) =>
          lazymatch src with
          | FC_S => exb_fstep fdef HK ST FZ
          | FC_D => exb_fstep fdef HK ST FZ
          | _ =>
            let F := fresh "F" in let D := fresh "D" in let ST' := fresh "ST" in
            ex_fetch segs pc F D;
            lazymatch type of D with
            | decode_any ?w = _ =>
              let mdo := eval vm_compute in (rmode_of_field (bv_unsigned rm) 0) in
              let md := lazymatch mdo with Some ?md => md end in
              let sgn := lazymatch src with FC_W => constr:(true) | FC_L => constr:(true) | FC_WU => constr:(false) | FC_LU => constr:(false) end in
              let bits := lazymatch src with FC_W => constr:(32%Z) | FC_WU => constr:(32%Z) | FC_L => constr:(64%Z) | FC_LU => constr:(64%Z) end in
              let e1 := eval vm_compute in (sr_get sr rs1) in
              lazymatch e1 with
              | ELit ?z1 =>
                let r := eval vm_compute in (fp_of_int (fp_format FMT_D) md sgn bits (bv_unsigned (Z_to_bv 64 z1))) in
                lazymatch r with (?res, ?fl) =>
                  let zr := eval vm_compute in (bv_unsigned (fpv_box FMT_D res)) in
                  pose proof (exb_fcvt_fx segs E L fr cs m rom pc sr log ms0 w FC_D src rd rs1 rm md FMT_D sgn bits z1 res zr fl
                                ST F (eq_refl _) D ltac:(exf_disj) ltac:(exf_disj) FZ ltac:(vm_cast_no_check (eq_refl (Some md)))
                                ltac:(vm_cast_no_check (eq_refl (Z_to_bv 64 z1)))
                                ltac:(vm_cast_no_check (eq_refl (res, fl))) ltac:(apply bv_eq; vm_cast_no_check (eq_refl zr))) as ST';
                  clear F D ST; rename ST' into ST; exb_reabs ST FZ end
              | _ => fail 100 "exq_fstep: fcvt from an integer register that is not closed:" e1 "at" pc
              end
            end
          end
      | _ => exb_fstep fdef HK ST FZ
      end
  end.

Ltac exq_adriveS_loop rounds fuel stops scr fdef HK ST FZ :=
  first [ exb_at_stop stops ST | exb_at_jalr ST
        | (exq_fstep fdef HK ST FZ; exb_norm ST;
           first [ exb_at_stop stops ST
                 | exb_autoS rounds fuel stops scr HK ST ltac:(fun scr' => exq_adriveS_loop rounds fuel stops scr' fdef HK ST FZ) ]) ].
Ltac exq_adriveS rounds fuel stops scr fdef HK ST FZ :=
  exb_autoS rounds fuel stops scr HK ST ltac:(fun scr' => exq_adriveS_loop rounds fuel stops scr' fdef HK ST FZ).
Ltac exq_adrive rounds fuel stops fdef HK ST FZ := exq_adriveS rounds fuel stops (SCR [] [] []) fdef HK ST FZ.
